/**
 * DynamoDB に保存されたチーム所有 Issue 詳細を返す endpoint です。
 */
routeApp.get('/api/teams/:teamId/issues/:issueId', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    const context = await requireTeamPermission(principal, teamId, 'viewer')

    const detail = await workItemDependencies.teamIssues.getTeamIssueDetail(
      principal.directoryId,
      teamId,
      issueId,
      {
        consistentIssueRead: true,
        includeComments: false,
      },
    )
    requireAssignedProjectPermission(principal, context, detail.issue.assignedProjectId, 'viewer')
    const entityKey = createWorkItemCollaborationEntityKey(principal.directoryId, teamId, issueId)
    const projectEntityKey = detail.issue.assignedProjectId
      ? createProjectCollaborationEntityKey(principal.directoryId, detail.issue.assignedProjectId)
      : undefined
    const collaborationReadBudget: CollaborationThreadReadBudget = {
      maxPages: TEAM_ISSUE_DETAIL_COMMENT_READ_MAX_PAGES,
      maxBytes: TEAM_ISSUE_DETAIL_COMMENT_MAX_BYTES,
      bytesRead: 2,
      pagesRead: 0,
    }
    const commentBackfillComplete = await workItemDependencies.collaboration.isTeamIssueCommentBackfillComplete(
      principal.directoryId,
    )
    const legacyCommentDetail = commentBackfillComplete
      ? undefined
      : await workItemDependencies.teamIssues.getTeamIssueDetail(
          principal.directoryId,
          teamId,
          issueId,
          {
            consistentIssueRead: true,
            eventLimit: LEGACY_COLLABORATION_EVENT_PREVIEW_LIMIT,
            newestEventsFirst: true,
            eventType: 'commented',
            legacyCommentIndexOnly: true,
          },
        )
    if (legacyCommentDetail) {
      requireAssignedProjectPermission(
        principal,
        context,
        legacyCommentDetail.issue.assignedProjectId,
        'viewer',
      )
      if (legacyCommentDetail.issue.assignedProjectId !== detail.issue.assignedProjectId) {
        throw new ProjectDataError(
          409,
          'WorkItemAuthorizationChanged',
          'Work Item assignment changed while comments were loading.',
        )
      }
    }
    const [collaborationComments, resolvedConfiguration, relationPage] = await Promise.all([
      readAllCollaborationThreadComments(workItemDependencies.collaboration, {
        entityKey,
        viewerMemberKey: principal.userKey,
        projectEntityKey,
        limit: 100,
        includeReplies: true,
        includeScopeState: false,
      }, collaborationReadBudget),
      workItemDependencies.workItemConfigurations.getTeamConfiguration(principal.directoryId, teamId),
      workItemDependencies.workItemConfigurations.listRelations(principal.directoryId, teamId, issueId),
    ])
    let customerImpact: TeamIssueDetailResponse['customerImpact']
    if (hasCustomerReadAccess(principal, { teamId })) {
      try {
        customerImpact = projectCustomerImpactSignal(
          await workspaceDependencies.customers.getWorkItemImpact(
            principal.directoryId,
            teamId,
            issueId,
          ),
          hasCustomerManagementAccess(principal, { teamId }),
        )
      } catch (error) {
        console.error('Customer impact was unavailable while loading Work Item detail.', {
          workspaceId: principal.directoryId,
          teamId,
          issueId,
          errorCode: error instanceof CustomerError ? error.code : 'CustomerImpactUnavailable',
        })
      }
    }
    const allCollaborationComments = collaborationComments.sort(
      compareMigrationAwareComments,
    )
    const visibleRelations = await filterVisibleWorkItemRelations(
      principal,
      context,
      teamId,
      relationPage.relations,
    )

    const canonicalCommentIds = new Set(allCollaborationComments.map((comment) => comment.id))
    const canonicalComments = allCollaborationComments
      .filter((comment) => !comment.deletedAt)
      .map(toTeamIssueDetailCommentResponse)
    const legacyComments = commentBackfillComplete
      ? []
      : (legacyCommentDetail?.comments ?? []).filter((comment) => !canonicalCommentIds.has(comment.id))
    const responseComments = mergeLegacyTeamIssueDetailComments(legacyComments, canonicalComments)
    enforceTeamIssueDetailCommentResponseBudget(responseComments)
    const hydratedDetail = await hydrateTeamIssueDetailResponse(
      {
        ...detail,
        comments: [],
        resolvedConfiguration,
        relations: visibleRelations,
        relationGraphRevision: relationPage.graphRevision,
        customerImpact,
      },
      principal.directoryId,
    )

    return c.json({
      ...hydratedDetail,
      comments: responseComments,
    })
  } catch (error) {
    return toWorkItemConfigurationErrorResponse(c, error)
  }
})

/**
 * Validates a Work Item schedule operation and returns its impact before mutation.
 */
routeApp.post('/api/teams/:teamId/issues/:issueId/schedule/preview', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const context = await requireTeamPermission(principal, teamId, 'member')
    const body = await readJson<Record<string, unknown>>(c.req) ?? {}
    const expectedRevision = readWorkItemExpectedRevision(body.expectedRevision)
    const operation = normalizeWorkItemScheduleOperation(body.operation)
    const [detail, relationPage] = await Promise.all([
      workItemDependencies.teamIssues.getTeamIssueDetail(
        principal.directoryId,
        teamId,
        issueId,
        { consistentIssueRead: true, eventLimit: 0 },
      ),
      workItemDependencies.workItemConfigurations.listRelations(
        principal.directoryId,
        teamId,
        issueId,
      ),
    ])
    requireAssignedProjectPermission(principal, context, detail.issue.assignedProjectId, 'member')
    if (detail.issue.revision !== expectedRevision) {
      throw new ProjectDataError(
        409,
        'WorkItemRevisionConflict',
        'Work Item changed. Reload and try again.',
      )
    }

    const visibleRelations = await filterVisibleWorkItemRelations(
      principal,
      context,
      teamId,
      relationPage.relations,
    )
    const recomputed = await recomputeWorkItemScheduleDependencyPreview(
      principal,
      detail.issue,
      operation,
      relationPage.graphRevision,
      visibleRelations.filter((relation) =>
        relation.sourceWorkItemId === issueId &&
        (relation.type === 'blocks' || relation.type === 'blockedBy')
      ).length,
      'viewer',
    )
    return c.json(recomputed.preview)
  } catch (error) {
    return toWorkItemConfigurationErrorResponse(c, error)
  }
})

/**
 * Recomputes and atomically persists an explicitly confirmed schedule dependency cascade.
 */
routeApp.post('/api/teams/:teamId/issues/:issueId/schedule/confirm', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }
  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const context = await requireTeamPermission(principal, teamId, 'member')
    const idempotencyKey = readRequiredWorkItemScheduleIdempotencyKey(
      c.req.header('Idempotency-Key'),
    )
    const body = await readJson<Record<string, unknown>>(c.req) ?? {}
    if (body.confirmed !== true) {
      throw new WorkItemScheduleError(
        400,
        'WorkItemScheduleConfirmationRequired',
        'Schedule dependency changes require explicit confirmation.',
      )
    }
    const expectedRevision = readWorkItemExpectedRevision(body.expectedRevision)
    const expectedPlanningRevision = readWorkItemScheduleGraphRevision(
      body.expectedPlanningRevision,
      'Planning revision',
    )
    const expectedRelationGraphRevision = readWorkItemScheduleGraphRevision(
      body.expectedRelationGraphRevision,
      'Relation graph revision',
    )
    const expectedEvaluatedRevisions = readWorkItemScheduleEvaluationRevisions(
      body.expectedEvaluatedRevisions,
    )
    const expectedImpacts = readWorkItemScheduleImpacts(body.expectedImpacts)
    const operation = normalizeWorkItemScheduleOperation(body.operation)
    const reservationRequest: ReserveIdempotencyRequest = {
      workspaceId: createWorkItemScheduleIdempotencyWorkspaceId(principal.directoryId),
      credentialId: createWorkItemScheduleIdempotencyUserId(
        principal.directoryId,
        principal.actorId,
      ),
      idempotencyKey,
      requestFingerprint: createWorkItemScheduleConfirmationFingerprint(
        c.req.method,
        new URL(c.req.url).pathname,
        body,
      ),
    }
    const response = await executeConfirmedWorkItemScheduleChange(
      c,
      principal,
      context,
      body,
      {
        teamId,
        workItemId: issueId,
        expectedRevision,
        expectedPlanningRevision,
        expectedRelationGraphRevision,
        expectedEvaluatedRevisions,
        expectedImpacts,
        operation,
        reservationRequest,
      },
    )
    return c.json(response)
  } catch (error) {
    return toWorkItemConfigurationErrorResponse(c, error)
  }
})

/**
 * Work Item Type の変更による影響を計算する endpoint です。
 */
routeApp.post('/api/teams/:teamId/issues/:issueId/work-item-type-preview', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }
  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const context = await requireTeamPermission(principal, teamId, 'member')
    const input = await readJson<Record<string, unknown>>(c.req) ?? {}
    const expectedRevision = readWorkItemExpectedRevision(input.expectedRevision)
    const targetWorkItemTypeId = readRequiredWorkItemTypeId(input.targetWorkItemTypeId)
    const detail = await workItemDependencies.teamIssues.getTeamIssueDetail(
      principal.directoryId,
      teamId,
      issueId,
      { consistentIssueRead: true, eventLimit: 0 },
    )
    if (detail.issue.revision !== expectedRevision) {
      throw new ProjectDataError(
        409,
        'WorkItemRevisionConflict',
        'Work Item changed. Reload and try again.',
      )
    }
    requireAssignedProjectPermission(principal, context, detail.issue.assignedProjectId, 'member')
    const proposedAssignedProjectId = 'assignedProjectId' in input
      ? readAssignedProjectId(input.assignedProjectId)
      : detail.issue.assignedProjectId
    if ('assignedProjectId' in input) {
      requireAssignedProjectPermission(
        principal,
        context,
        proposedAssignedProjectId,
        'member',
      )
    }
    const resolvedConfiguration = await workItemDependencies.workItemConfigurations.getTeamConfiguration(
      principal.directoryId,
      teamId,
    )
    const preview = previewWorkItemTypeChange(
      resolvedConfiguration.configuration,
      detail.issue.workItemTypeId,
      detail.issue.workflowStatusId,
      detail.issue.customFieldValues,
      targetWorkItemTypeId,
      proposedAssignedProjectId ?? undefined,
      expectedRevision,
    )
    return c.json(preview)
  } catch (error) {
    return toWorkItemConfigurationErrorResponse(c, error)
  }
})

/**
 * DynamoDB に保存されたチーム所有 Issue を更新する endpoint です。
 */
routeApp.patch('/api/teams/:teamId/issues/:issueId', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const context = await requireTeamPermission(principal, teamId, 'member')
    const input = await readJson<PublicUpdateTeamIssueRequestBody>(c.req) ?? {}
    rejectInternalWorkItemUpdateFields(input)
    const body = normalizeTeamIssueInput(
      input,
      context.team,
    )
    const expectedRevision = readWorkItemExpectedRevision(body.expectedRevision)
    const detail = await workItemDependencies.teamIssues.getTeamIssueDetail(
      principal.directoryId,
      teamId,
      issueId,
      { consistentIssueRead: true, eventLimit: 0 },
    )
    requireAssignedProjectPermission(principal, context, detail.issue.assignedProjectId, 'member')
    requireAssignedProjectPermission(
      principal,
      context,
      readAssignedProjectId(body.assignedProjectId),
      'member',
    )

    const resolvedConfiguration = await workItemDependencies.workItemConfigurations.getTeamConfiguration(
      principal.directoryId,
      teamId,
    )
    const configuredBody = await prepareConfiguredUpdateWorkItem(
      principal.directoryId,
      teamId,
      detail.issue,
      body,
      resolvedConfiguration,
    )

    let authorizationSnapshot: WorkItemAuthorizationSnapshot | undefined
    const changesSchedule =
      'schedule' in configuredBody &&
      configuredBody.schedule !== undefined &&
      stableDigestStringify(configuredBody.schedule) !==
        stableDigestStringify(detail.issue.schedule)
    const changesAssignedProject =
      'assignedProjectId' in configuredBody &&
      readAssignedProjectId(configuredBody.assignedProjectId) !== detail.issue.assignedProjectId
    if (changesSchedule) {
      try {
        authorizationSnapshot = await createDependencyFencedWorkItemAuthorizationSnapshot(
          principal,
          teamId,
          issueId,
        )
      } catch (error) {
        if (
          error instanceof PlanningError &&
          error.code === 'PlanningWorkItemDependencyInUse'
        ) {
          throw new WorkItemScheduleError(
            409,
            'WorkItemScheduleConfirmationRequired',
            'Preview and explicitly confirm schedule changes for Work Items with dependencies.',
          )
        }
        if (error instanceof PlanningError) {
          throw new WorkItemScheduleError(error.status, error.code, error.message)
        }
        throw error
      }
    } else if (changesAssignedProject) {
      authorizationSnapshot = await createPlanningFencedWorkItemAuthorizationSnapshot(principal)
    }

    if ('assigneeUserId' in configuredBody) {
      await requireActiveWorkspaceAssignee(
        principal.directoryId,
        readTeamIssueAssigneeUserId(configuredBody),
      )
    }

    const response = await hydrateUpdateTeamIssueResponse(
      await workItemDependencies.teamIssues.updateTeamIssue(
        principal.directoryId,
        teamId,
        issueId,
        {
          ...configuredBody,
          expectedRevision,
          ...(authorizationSnapshot ? { authorizationSnapshot } : {}),
        },
        principal.userKey,
        createApiMutationContext(c, principal, {
          teamId,
          issueId,
          ...configuredBody,
          expectedRevision,
        }),
      ),
    )
    await projectWorkItemMutationSearchDocumentBestEffort(
      principal.directoryId,
      response.issue,
      'Work Item update',
    )
    return c.json(response)
  } catch (error) {
    return toWorkItemConfigurationErrorResponse(c, error)
  }
})

/** Maximum legacy event rows evaluated in one request before migration completes. */
const LEGACY_COLLABORATION_EVENT_PREVIEW_LIMIT = 50
/** Prefix that keeps legacy event cursors distinct from canonical cursors. */
const LEGACY_COLLABORATION_CURSOR_PREFIX = 'legacy.'
/** Legacy cursor token accepted for already-issued transitional cursors. */
const LEGACY_COLLABORATION_INITIAL_CURSOR = 'initial'
/** Prefix for a cursor that merges canonical and legacy root-comment streams. */
const MIGRATION_AWARE_COLLABORATION_CURSOR_PREFIX = 'mixed.'

/**
 * Parses the collaboration endpoint page limit before selecting a migration reader.
 *
 * @param value - Raw query-string page limit.
 * @returns A safe integer page limit, or undefined when omitted.
 */
function readCollaborationPageLimit(value: string | undefined): number | undefined {
  if (value === undefined) return undefined
  const limit = Number(value)
  if (!Number.isSafeInteger(limit) || limit < 1) {
    throw new CollaborationError(400, 'InvalidCollaborationCursor', 'Page limit is invalid.')
  }
  return limit
}

/** Cursor state used to merge canonical and legacy root-comment streams. */
type MigrationAwareCollaborationCursor = {
  /** Cursor schema version. */
  version: 1
  /** Workspace directory bound to the cursor. */
  directoryId: string
  /** Team bound to the cursor. */
  teamId: string
  /** Issue bound to the cursor. */
  issueId: string
  /** Canonical Collaboration cursor before the next unread root, when applicable. */
  canonicalCursor?: string
  /** Legacy Team Issue event cursor before the next unread root, when applicable. */
  legacyEventCursor?: string
  /** Whether the canonical stream has been exhausted. */
  canonicalExhausted: boolean
  /** Whether the legacy stream has been exhausted. */
  legacyExhausted: boolean
  /** Creation timestamp of the last root emitted by the merged page. */
  lastEmittedCreatedAt?: string
  /** Stable ID of the last root emitted by the merged page. */
  lastEmittedCommentId?: string
}

/**
 * Team-owned Work Item の root comments、replies、watch、presence を page 取得します。
 */
routeApp.get('/api/teams/:teamId/issues/:issueId/collaboration', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    const { context, detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'viewer')
    const entityKey = createWorkItemCollaborationEntityKey(principal.directoryId, teamId, issueId)
    const projectEntityKey = detail.issue.assignedProjectId
      ? createProjectCollaborationEntityKey(principal.directoryId, detail.issue.assignedProjectId)
      : undefined
    const limitValue = c.req.query('limit')
    const limit = readCollaborationPageLimit(limitValue)
    const requestedRootCommentId = c.req.query('rootCommentId')
    const requestedCursor = c.req.query('cursor')
    const commentBackfillComplete = await workItemDependencies.collaboration.isTeamIssueCommentBackfillComplete(
      principal.directoryId,
    )
    const migrationCursor = decodeMigrationAwareCollaborationCursor(
      requestedCursor,
      principal.directoryId,
      teamId,
      issueId,
    )
    const isLegacyPage = !requestedRootCommentId &&
      requestedCursor?.startsWith(LEGACY_COLLABORATION_CURSOR_PREFIX) === true
    const legacyEventCursorToken = isLegacyPage
      ? requestedCursor.slice(LEGACY_COLLABORATION_CURSOR_PREFIX.length)
      : undefined
    const legacyEventCursor = legacyEventCursorToken === LEGACY_COLLABORATION_INITIAL_CURSOR
      ? undefined
      : legacyEventCursorToken
    if (isLegacyPage && commentBackfillComplete) {
      throw new CollaborationError(400, 'InvalidCollaborationCursor', 'Collaboration cursor is invalid.')
    }
    if (migrationCursor && requestedRootCommentId !== undefined) {
      throw new CollaborationError(400, 'InvalidCollaborationCursor', 'Collaboration cursor is invalid.')
    }
    if (
      isLegacyPage &&
      legacyEventCursorToken !== LEGACY_COLLABORATION_INITIAL_CURSOR &&
      !legacyEventCursor
    ) {
      throw new CollaborationError(400, 'InvalidCollaborationCursor', 'Legacy comment cursor is invalid.')
    }
    const canWrite = canWriteTeamIssue(principal, context, detail.issue.assignedProjectId)

    if (requestedRootCommentId) {
      const replies = await workItemDependencies.collaboration.getThread({
        entityKey,
        viewerMemberKey: principal.userKey,
        projectEntityKey,
        rootCommentId: readOptionalCommentId(requestedRootCommentId, 'Root comment ID'),
        cursor: requestedCursor,
        legacyCursorCompatible: true,
        limit: limit === undefined ? 20 : Math.min(limit, 20),
      })
      const responseComments = [...replies.comments].reverse().map((comment) =>
        toCollaborationCommentResponse(
          comment,
          principal,
          context,
          detail.issue,
          replies.threadResolved === true,
        )
      )
      enforceCollaborationCommentResponseBudget(responseComments)
      return c.json({
        // Store は最新順で page し、thread 内は古い順に描画できるよう反転して返す。
        comments: responseComments,
        ...(replies.nextCursor ? { nextCursor: replies.nextCursor } : {}),
        replyRootCommentId: requestedRootCommentId,
        watch: replies.watch,
        presence: replies.presence,
        capabilities: {
          canComment: canWrite,
          canReact: canWrite,
          canWatch: principal.workspaceRole !== 'guest',
        },
      })
    }

    const rootLimit = limit === undefined ? 10 : Math.min(Math.max(limit, 1), 20)
    const retainMixedCursorLegacyComments = migrationCursor?.legacyEventCursor !== undefined
    const migrationPage = (!commentBackfillComplete || migrationCursor !== undefined) && !isLegacyPage
      ? await readMigrationAwareRootPage({
          collaboration: workItemDependencies.collaboration,
          teamIssues: workItemDependencies.teamIssues,
          directoryId: principal.directoryId,
          teamId,
          issueId,
          entityKey,
          viewerMemberKey: principal.userKey,
          projectEntityKey,
          limit: rootLimit,
          cursor: migrationCursor ?? (requestedCursor === undefined
            ? undefined
            : {
                version: 1,
                directoryId: principal.directoryId,
                teamId,
                issueId,
                canonicalCursor: requestedCursor,
                canonicalExhausted: false,
                legacyExhausted: false,
              }),
          validateLegacyDetail: (legacyDetail) => {
            requireAssignedProjectPermission(
              principal,
              context,
              legacyDetail.issue.assignedProjectId,
              'viewer',
            )
            if (legacyDetail.issue.assignedProjectId !== detail.issue.assignedProjectId) {
              throw new CollaborationError(
                409,
                'CollaborationConflict',
                'Work Item assignment changed while comments were loading.',
              )
            }
          },
          shouldIncludeLegacyComment: async (comment) => {
            const storedComment = await workItemDependencies.collaboration.getCommentSnapshot({
              entityKey,
              commentId: comment.id,
            })
            return !storedComment?.deletedAt && (!storedComment || retainMixedCursorLegacyComments)
          },
        })
      : undefined
    const roots = migrationPage
      ? {
          comments: migrationPage.canonicalComments,
          ...(migrationPage.nextCursor ? { nextCursor: migrationPage.nextCursor } : {}),
          watch: migrationPage.watch,
          presence: migrationPage.presence,
        }
      : await workItemDependencies.collaboration.getThread({
          entityKey,
          viewerMemberKey: principal.userKey,
          projectEntityKey,
          // The legacy.<event-cursor> namespace belongs to the Team Issue event
          // fallback below, not to the Collaboration discussion reader.
          cursor: isLegacyPage ? undefined : migrationCursor?.canonicalCursor ?? requestedCursor,
          legacyCursorCompatible: true,
          limit: rootLimit,
        })
    const replyPages = isLegacyPage
      ? []
      : await Promise.all(
          roots.comments.map((root) => workItemDependencies.collaboration.getThread({
            entityKey,
            viewerMemberKey: principal.userKey,
            projectEntityKey,
            rootCommentId: root.id,
            legacyCursorCompatible: true,
            limit: 5,
            includeScopeState: false,
          })),
        )
    const comments = isLegacyPage
      ? []
      : roots.comments.flatMap((root, index) => [
          root,
          ...[...(replyPages[index]?.comments ?? [])].reverse(),
        ])
    const replyPagesByRootId = new Map(
      roots.comments.map((root, index) => [root.id, replyPages[index]] as const),
    )
    // Keep canonical IDs from the probe page for legacy deduplication even
    // though that page has already been consumed before the legacy cursor.
    const storedCommentIds = new Set([
      ...roots.comments.map((comment) => comment.id),
      ...comments.map((comment) => comment.id),
    ])
    const legacyEventLimit = limit === undefined
      ? LEGACY_COLLABORATION_EVENT_PREVIEW_LIMIT
      : Math.min(
          Math.max(limit - (isLegacyPage ? 0 : roots.comments.length), 0),
          LEGACY_COLLABORATION_EVENT_PREVIEW_LIMIT,
        )
    const legacyDetail = !migrationPage && !commentBackfillComplete &&
      legacyEventLimit > 0 &&
      (isLegacyPage || !roots.nextCursor)
      ? await workItemDependencies.teamIssues.getTeamIssueDetail(
          principal.directoryId,
          teamId,
          issueId,
          {
            consistentIssueRead: true,
            eventLimit: legacyEventLimit,
            newestEventsFirst: true,
            eventType: 'commented',
            eventCursor: legacyEventCursor,
            legacyCommentIndexOnly: true,
          },
        )
      : undefined
    if (legacyDetail) {
      requireAssignedProjectPermission(
        principal,
        context,
        legacyDetail.issue.assignedProjectId,
        'viewer',
      )
      if (legacyDetail.issue.assignedProjectId !== detail.issue.assignedProjectId) {
        throw new CollaborationError(
          409,
          'CollaborationConflict',
          'Work Item assignment changed while comments were loading.',
        )
      }
    }
    const legacyComments = migrationPage
      ? migrationPage.legacyComments.map(toLegacyCollaborationCommentResponse)
      : (await Promise.all(
          (legacyDetail?.comments ?? [])
            .filter((comment) => !storedCommentIds.has(comment.id))
            .map(async (comment) => {
              const storedComment = await workItemDependencies.collaboration.getCommentSnapshot({
                entityKey,
                commentId: comment.id,
              })
              return storedComment
                ? undefined
                : toLegacyCollaborationCommentResponse(comment)
            }),
        )).flatMap((comment) => comment ? [comment] : [])
    const collaborationComments = migrationPage
      ? migrationPage.orderedComments.flatMap((root) => {
          if (root.source === 'legacy') {
            const legacyComment = legacyComments.find((comment) => comment.id === root.comment.id)
            return legacyComment ? [legacyComment] : []
          }
          const replyPage = replyPagesByRootId.get(root.comment.id)
          return [
            toCollaborationCommentResponse(
              root.comment,
              principal,
              context,
              detail.issue,
              replyPage?.threadResolved === true,
            ),
            ...(replyPage?.comments ?? []).reverse().map((comment) =>
              toCollaborationCommentResponse(
                comment,
                principal,
                context,
                detail.issue,
                replyPage?.threadResolved === true,
              ),
            ),
          ]
        })
      : comments.map((comment) =>
          toCollaborationCommentResponse(
            comment,
            principal,
            context,
            detail.issue,
            replyPages.some((page, index) =>
              roots.comments[index]?.id === comment.rootCommentId && page.threadResolved === true
            ),
          ),
        )
    if (!migrationPage) {
      collaborationComments.push(...legacyComments)
    }
    enforceCollaborationCommentResponseBudget(collaborationComments)
    const replyNextCursors = Object.fromEntries(
      roots.comments.flatMap((root, index) => {
        const cursor = replyPages[index]?.nextCursor
        return cursor ? [[root.id, cursor] as const] : []
      }),
    )
    return c.json({
      comments: collaborationComments,
      ...(isLegacyPage
        ? legacyDetail?.nextEventCursor
          ? { nextCursor: `${LEGACY_COLLABORATION_CURSOR_PREFIX}${legacyDetail.nextEventCursor}` }
          : {}
        : roots.nextCursor
          ? { nextCursor: roots.nextCursor }
          : legacyDetail?.nextEventCursor
            ? { nextCursor: `${LEGACY_COLLABORATION_CURSOR_PREFIX}${legacyDetail.nextEventCursor}` }
            : {}),
      ...(Object.keys(replyNextCursors).length > 0 ? { replyNextCursors } : {}),
      watch: roots.watch,
      presence: roots.presence,
      capabilities: {
        canComment: canWrite,
        canReact: canWrite,
        canWatch: principal.workspaceRole !== 'guest',
      },
    })
  } catch (error) {
    return toCollaborationErrorResponse(c, error)
  }
})

/** Team-owned Work Item の curated context items を cursor page で返します。 */
routeApp.get('/api/teams/:teamId/issues/:issueId/context-items', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    const { context, detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'viewer')
    const limitValue = c.req.query('limit')
    const limit = limitValue === undefined ? undefined : Number(limitValue)
    const entityKey = createWorkItemCollaborationEntityKey(
      principal.directoryId,
      teamId,
      issueId,
    )
    const page = await workItemDependencies.collaboration.getCuratedContext({
      entityKey,
      limit,
      cursor: c.req.query('cursor'),
      capabilities: createCuratedContextCapabilities(principal, context, detail.issue),
    })
    const currentPrincipal = await assertCuratedContextScopeUnchanged(
      principal,
      teamId,
      issueId,
      'viewer',
      detail.issue.assignedProjectId,
      accessToken,
      c,
    )
    const reconciledItems = await reconcileCuratedContextSourcesForViewer(
      currentPrincipal,
      teamId,
      issueId,
      entityKey,
      page.items,
    )
    const finalPrincipal = await assertCuratedContextScopeUnchanged(
      currentPrincipal,
      teamId,
      issueId,
      'viewer',
      detail.issue.assignedProjectId,
      accessToken,
      c,
    )
    const finalScope = await loadAuthorizedTeamIssue(
      finalPrincipal,
      teamId,
      issueId,
      'viewer',
    )
    return c.json({
      ...page,
      items: reconciledItems,
      capabilities: createCuratedContextCapabilities(
        finalPrincipal,
        finalScope.context,
        finalScope.detail.issue,
      ),
    })
  } catch (error) {
    return toCollaborationErrorResponse(c, error)
  }
})

/** Curated context item の immutable revision history を cursor page で返します。 */
routeApp.get(
  '/api/teams/:teamId/issues/:issueId/context-items/:contextItemId/revisions',
  async (c) => {
    const accessToken = readBearerAccessToken(c)
    const teamId = c.req.param('teamId')
    const issueId = c.req.param('issueId')
    const contextItemId = c.req.param('contextItemId')

    if (!accessToken) {
      return c.json({ message: 'Bearer token is required.' }, 401)
    }

    try {
      const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
      const { detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'viewer')
      const entityKey = createWorkItemCollaborationEntityKey(
        principal.directoryId,
        teamId,
        issueId,
      )
      const limitValue = c.req.query('limit')
      const page = await workItemDependencies.collaboration.getCuratedContextRevisions({
        entityKey,
        itemId: contextItemId,
        limit: limitValue === undefined ? undefined : Number(limitValue),
        cursor: c.req.query('cursor'),
      })
      const currentPrincipal = await assertCuratedContextScopeUnchanged(
        principal,
        teamId,
        issueId,
        'viewer',
        detail.issue.assignedProjectId,
        accessToken,
        c,
      )
      const reconciledItems = await reconcileCuratedContextSourcesForViewer(
        currentPrincipal,
        teamId,
        issueId,
        entityKey,
        page.items,
      )
      await assertCuratedContextScopeUnchanged(
        currentPrincipal,
        teamId,
        issueId,
        'viewer',
        detail.issue.assignedProjectId,
        accessToken,
        c,
      )
      return c.json({
        ...page,
        items: reconciledItems,
      })
    } catch (error) {
      return toCollaborationErrorResponse(c, error)
    }
  },
)

/** Team-owned Work Item に human-curated context item を追加します。 */
routeApp.post('/api/teams/:teamId/issues/:issueId/context-items', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const request = readCreateCuratedContextItemRequest(await readJson<unknown>(c.req))
    const { context, detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'member')
    const entityKey = createWorkItemCollaborationEntityKey(principal.directoryId, teamId, issueId)
    const auditContext = createApiMutationContext(c, principal, { teamId, issueId, ...request })
    const replayed = await workItemDependencies.collaboration.getCuratedContextMutationReplay({
      entityKey,
      operation: 'create',
      auditContext,
    })
    if (replayed) {
      return c.json({
        item: await requirePermissionSafeCuratedContextItem(
          principal,
          teamId,
          issueId,
          entityKey,
          replayed,
          detail.issue.assignedProjectId,
          accessToken,
          c,
        ),
      }, 201)
    }
    const mentionMemberKeys = request.mentionMemberKeys ?? []
    await requireValidCommentMentions(
      principal.directoryId,
      mentionMemberKeys,
      context,
      detail.issue.assignedProjectId,
    )
    const projectEntityKey = detail.issue.assignedProjectId
      ? createProjectCollaborationEntityKey(principal.directoryId, detail.issue.assignedProjectId)
      : undefined
    const resolvedSource = request.source
      ? await resolveCuratedContextSource(principal, teamId, issueId, entityKey, request.source)
      : undefined
    const item = await workItemDependencies.collaboration.createCuratedContextItem({
      workspaceId: principal.directoryId,
      teamId,
      issueId,
      workItemTitle: detail.issue.title,
      entityKey,
      projectId: detail.issue.assignedProjectId,
      projectEntityKey,
      actor: createCuratedContextActorSnapshot(principal),
      authorizationSnapshot: {
        memberKey: principal.userKey,
        workspaceMemberVersion: principal.workspaceMember.version,
        ...(principal.enterpriseIdentityControlRevision === undefined
          ? {}
          : { enterpriseControlRevision: principal.enterpriseIdentityControlRevision }),
      },
      kind: request.kind,
      title: request.title,
      body: request.body,
      ...(resolvedSource ? { source: resolvedSource.source } : {}),
      ...(resolvedSource?.documentAuthorizationSnapshot
        ? { sourceAuthorizationSnapshot: resolvedSource.documentAuthorizationSnapshot }
        : {}),
      ...(resolvedSource?.activityAuthorizationSnapshot
        ? { activitySourceAuthorizationSnapshot: resolvedSource.activityAuthorizationSnapshot }
        : {}),
      mentionMemberKeys,
      ...(request.supersedesItemId ? { supersedesItemId: request.supersedesItemId } : {}),
      notificationCandidates: mentionMemberKeys.map((memberKey) => ({
        memberKey,
        reason: 'mention',
      })),
      automaticWatcherCandidates: createTeamIssueAutomaticWatcherCandidates(detail.issue),
      deepLink: createTeamIssueDeepLink(teamId, issueId),
      auditContext,
    })
    await projectWorkspaceSearchDocumentBestEffort(
      () => createCuratedContextItemWorkspaceSearchDocument({
        workspaceId: principal.directoryId,
        item,
        projectId: detail.issue.assignedProjectId,
      }),
      'curated context creation',
    )
    if (request.supersedesItemId) {
      await deleteWorkspaceSearchDocumentBestEffort(
        principal.directoryId,
        'context-item',
        `${createTeamIssueAuditEntityId(teamId, issueId)}/context-item/${request.supersedesItemId}`,
        'curated context supersession',
      )
    }
    return c.json({
      item: await requirePermissionSafeCuratedContextItem(
        principal,
        teamId,
        issueId,
        entityKey,
        item,
        detail.issue.assignedProjectId,
        accessToken,
        c,
      ),
    }, 201)
  } catch (error) {
    return toCollaborationErrorResponse(c, error)
  }
})

/** Curated context item を optimistic revision 条件付きで更新します。 */
routeApp.patch('/api/teams/:teamId/issues/:issueId/context-items/:contextItemId', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')
  const contextItemId = c.req.param('contextItemId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const request = readUpdateCuratedContextItemRequest(await readJson<unknown>(c.req))
    const { context, detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'member')
    const entityKey = createWorkItemCollaborationEntityKey(principal.directoryId, teamId, issueId)
    const auditContext = createApiMutationContext(c, principal, {
      teamId,
      issueId,
      contextItemId,
      ...request,
    })
    const replayed = await workItemDependencies.collaboration.getCuratedContextMutationReplay({
      entityKey,
      operation: 'update',
      itemId: contextItemId,
      auditContext,
    })
    if (replayed) {
      return c.json({
        item: await requirePermissionSafeCuratedContextItem(
          principal,
          teamId,
          issueId,
          entityKey,
          replayed,
          detail.issue.assignedProjectId,
          accessToken,
          c,
        ),
      })
    }
    if (request.mentionMemberKeys) {
      await requireValidCommentMentions(
        principal.directoryId,
        request.mentionMemberKeys,
        context,
        detail.issue.assignedProjectId,
      )
    }
    const projectEntityKey = detail.issue.assignedProjectId
      ? createProjectCollaborationEntityKey(principal.directoryId, detail.issue.assignedProjectId)
      : undefined
    const item = await workItemDependencies.collaboration.updateCuratedContextItem({
      workspaceId: principal.directoryId,
      teamId,
      issueId,
      workItemTitle: detail.issue.title,
      entityKey,
      projectId: detail.issue.assignedProjectId,
      projectEntityKey,
      itemId: contextItemId,
      actor: createCuratedContextActorSnapshot(principal),
      authorizationSnapshot: {
        memberKey: principal.userKey,
        workspaceMemberVersion: principal.workspaceMember.version,
        ...(principal.enterpriseIdentityControlRevision === undefined
          ? {}
          : { enterpriseControlRevision: principal.enterpriseIdentityControlRevision }),
      },
      expectedRevision: request.expectedRevision,
      ...(request.kind ? { kind: request.kind } : {}),
      ...(request.state ? { state: request.state } : {}),
      ...(request.title !== undefined ? { title: request.title } : {}),
      ...(request.body !== undefined ? { body: request.body } : {}),
      ...(request.mentionMemberKeys ? { mentionMemberKeys: request.mentionMemberKeys } : {}),
      notificationCandidates: (request.mentionMemberKeys ?? []).map((memberKey) => ({
        memberKey,
        reason: 'mention',
      })),
      automaticWatcherCandidates: createTeamIssueAutomaticWatcherCandidates(detail.issue),
      deepLink: createTeamIssueDeepLink(teamId, issueId),
      auditContext,
    })
    if (item.state === 'superseded') {
      await deleteWorkspaceSearchDocumentBestEffort(
        principal.directoryId,
        'context-item',
        `${createTeamIssueAuditEntityId(teamId, issueId)}/context-item/${item.id}`,
        'curated context update',
      )
    } else {
      await projectWorkspaceSearchDocumentBestEffort(
        () => createCuratedContextItemWorkspaceSearchDocument({
          workspaceId: principal.directoryId,
          item,
          projectId: detail.issue.assignedProjectId,
        }),
        'curated context update',
      )
    }
    return c.json({
      item: await requirePermissionSafeCuratedContextItem(
        principal,
        teamId,
        issueId,
        entityKey,
        item,
        detail.issue.assignedProjectId,
        accessToken,
        c,
      ),
    })
  } catch (error) {
    return toCollaborationErrorResponse(c, error)
  }
})

/** Root thread の accepted resolution history を cursor page で返します。 */
routeApp.get(
  '/api/teams/:teamId/issues/:issueId/comments/:rootCommentId/accepted-resolutions',
  async (c) => {
    const accessToken = readBearerAccessToken(c)
    const teamId = c.req.param('teamId')
    const issueId = c.req.param('issueId')
    const rootCommentId = c.req.param('rootCommentId')

    if (!accessToken) {
      return c.json({ message: 'Bearer token is required.' }, 401)
    }

    try {
      const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
      const { detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'viewer')
      const limitValue = c.req.query('limit')
      const page = await workItemDependencies.collaboration.getAcceptedResolutionHistory({
        entityKey: createWorkItemCollaborationEntityKey(
          principal.directoryId,
          teamId,
          issueId,
        ),
        rootCommentId,
        limit: limitValue === undefined ? undefined : Number(limitValue),
        cursor: c.req.query('cursor'),
      })
      await assertCuratedContextScopeUnchanged(
        principal,
        teamId,
        issueId,
        'viewer',
        detail.issue.assignedProjectId,
        accessToken,
        c,
      )
      return c.json(page)
    } catch (error) {
      return toCollaborationErrorResponse(c, error)
    }
  },
)

/** Root thread の accepted resolution を選択・差し替え・再要約します。 */
routeApp.put('/api/teams/:teamId/issues/:issueId/comments/:rootCommentId/accepted-resolution', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')
  const rootCommentId = c.req.param('rootCommentId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const request = readSetAcceptedResolutionRequest(await readJson<unknown>(c.req))
    const { context, detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'viewer')
    const comment = await workItemDependencies.collaboration.setAcceptedResolution({
      workspaceId: principal.directoryId,
      teamId,
      issueId,
      workItemTitle: detail.issue.title,
      entityKey: createWorkItemCollaborationEntityKey(principal.directoryId, teamId, issueId),
      projectId: detail.issue.assignedProjectId,
      projectEntityKey: detail.issue.assignedProjectId
        ? createProjectCollaborationEntityKey(principal.directoryId, detail.issue.assignedProjectId)
        : undefined,
      assigneeMemberKey: detail.issue.assigneeUserId,
      rootCommentId,
      actor: createCuratedContextActorSnapshot(principal),
      authorizationSnapshot: {
        memberKey: principal.userKey,
        workspaceMemberVersion: principal.workspaceMember.version,
        ...(principal.enterpriseIdentityControlRevision === undefined
          ? {}
          : { enterpriseControlRevision: principal.enterpriseIdentityControlRevision }),
      },
      expectedThreadVersion: request.expectedThreadVersion,
      commentId: request.commentId,
      summary: request.summary,
      canModerate: canManageTeamIssueCollaboration(
        principal,
        context,
        detail.issue.assignedProjectId,
      ) || detail.issue.assigneeUserId === principal.userKey,
      deepLink: createTeamIssueDeepLink(teamId, issueId),
      auditContext: createApiMutationContext(c, principal, {
        teamId,
        issueId,
        rootCommentId,
        ...request,
      }),
    })
    const currentPrincipal = await assertCuratedContextScopeUnchanged(
      principal,
      teamId,
      issueId,
      'viewer',
      detail.issue.assignedProjectId,
      accessToken,
      c,
    )
    const current = await loadAuthorizedTeamIssue(currentPrincipal, teamId, issueId, 'viewer')
    return c.json({
      comment: toCollaborationCommentResponse(
        comment,
        currentPrincipal,
        current.context,
        current.detail.issue,
      ),
    })
  } catch (error) {
    return toCollaborationErrorResponse(c, error)
  }
})

/**
 * DynamoDB にチーム所有 Issue のコメントを作成する endpoint です。
 */
routeApp.post('/api/teams/:teamId/issues/:issueId/comments', async (c) => {
  const accessToken = readBearerAccessToken(c)
  const teamId = c.req.param('teamId')
  const issueId = c.req.param('issueId')

  if (!accessToken) {
    return c.json({ message: 'Bearer token is required.' }, 401)
  }

  if (!teamId || !issueId) {
    return c.json({ message: 'Team ID and issue ID are required.' }, 400)
  }

  try {
    const principal = await authenticateWorkspacePrincipal(accessToken, undefined, c)
    requireWorkspaceBusinessWrite(principal)
    const body = await readJson<CreateTeamIssueCommentRequestBody>(c.req) ?? {}
    const modernContract = body.bodyMarkdown !== undefined
    const { context, detail } = await loadAuthorizedTeamIssue(principal, teamId, issueId, 'member')
    const mentionMemberKeys = readCommentMentionMemberKeys(body.mentionMemberKeys)
    await requireValidCommentMentions(
      principal.directoryId,
      mentionMemberKeys,
      context,
      detail.issue.assignedProjectId,
    )
    const entityKey = createWorkItemCollaborationEntityKey(principal.directoryId, teamId, issueId)
    const projectEntityKey = detail.issue.assignedProjectId
      ? createProjectCollaborationEntityKey(principal.directoryId, detail.issue.assignedProjectId)
      : undefined
    const automaticWatcherCandidates = createTeamIssueAutomaticWatcherCandidates(detail.issue)
    const authorizationConditionChecks =
      await createCollaborationCommentAuthorizationConditionChecks(
        principal,
        context,
        teamId,
        detail.issue.assignedProjectId,
      )
    const comment = await workItemDependencies.collaboration.createComment({
      workspaceId: principal.directoryId,
      teamId,
      issueId,
      workItemTitle: detail.issue.title,
      entityKey,
      projectId: detail.issue.assignedProjectId,
      projectEntityKey,
      assigneeMemberKey: detail.issue.assigneeUserId,
      actorMemberKey: principal.userKey,
      bodyMarkdown: readRequiredCommentBody(body.bodyMarkdown ?? body.body),
      parentCommentId: readOptionalCommentId(body.parentCommentId, 'Parent comment ID'),
      mentionMemberKeys,
      automaticWatcherCandidates,
      deepLink: createTeamIssueDeepLink(teamId, issueId),
      authorizationConditionChecks,
      auditContext: createApiMutationContext(c, principal, { teamId, issueId, ...body }),
    })
    const activity = {
      id: comment.id,
      type: 'commented' as const,
      actorUserId: principal.userKey,
      summary: body.parentCommentId ? 'Reply was added.' : 'Comment was added.',
      createdAt: comment.createdAt,
    }
    await projectWorkspaceSearchDocumentBestEffort(
      () => createCommentSearchDocument(
        principal.directoryId,
        teamId,
        detail.issue,
        comment,
      ),
      'comment creation',
    )

    return modernContract
      ? c.json({
          comment: toCollaborationCommentResponse(comment, principal, context, detail.issue),
          activity,
        }, 201)
      : c.json({
          comment: {
            id: comment.id,
            actorUserId: comment.authorMemberKey,
            body: comment.bodyMarkdown,
            createdAt: comment.createdAt,
          },
          activity,
        }, 201)
  } catch (error) {
    return toCollaborationErrorResponse(c, error)
  }
})

